import{_ as i,o as a,c as t,a2 as r}from"./chunks/framework.CBxkvBm_.js";const u=JSON.parse('{"title":"Constrained Horn Clauses (Spacer), IC3/PDR & Certified Verification","description":"","frontmatter":{},"headers":[],"relativePath":"algorithms/verification-chc.md","filePath":"algorithms/verification-chc.md"}'),o={name:"algorithms/verification-chc.md"};function s(n,e,c,l,d,m){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="constrained-horn-clauses-spacer-ic3-pdr-certified-verification" tabindex="-1">Constrained Horn Clauses (Spacer), IC3/PDR &amp; Certified Verification <a class="header-anchor" href="#constrained-horn-clauses-spacer-ic3-pdr-certified-verification" aria-label="Permalink to &quot;Constrained Horn Clauses (Spacer), IC3/PDR &amp; Certified Verification&quot;">​</a></h1><p><strong>Implementation</strong>:</p><ul><li>Spacer CHC &amp; IC3/PDR: <a href="https://github.com/modelscript/modelscript/tree/main/packages/runtime/src/formal/chc/" target="_blank" rel="noreferrer"><code>packages/runtime/src/formal/chc/</code></a> and <a href="https://github.com/modelscript/modelscript/tree/main/packages/runtime/src/formal/ic3_engine.ts" target="_blank" rel="noreferrer"><code>packages/runtime/src/formal/ic3_engine.ts</code></a></li><li>Stochastic Martingale Barrier Certificates: <code>StochasticBarrierSynthesizer</code> in <a href="https://github.com/modelscript/modelscript/tree/main/packages/runtime/src/analysis/wasm_stochastic_barrier.ts" target="_blank" rel="noreferrer"><code>packages/runtime/src/analysis/wasm_stochastic_barrier.ts</code></a></li><li>WebGPU Datalog / OWL 2 RL Saturation Reasoner: <code>WebGPUOntologyReasoner</code> &amp; <code>BitsetGraph</code> in <a href="https://github.com/modelscript/modelscript/tree/main/packages/runtime/src/gpu/webgpu_reasoner.ts" target="_blank" rel="noreferrer"><code>packages/runtime/src/gpu/webgpu_reasoner.ts</code></a></li><li>ISO 26262 / DO-178C Back-to-Back Equivalence Verification: <code>B2BEquivalenceVerifier</code> in <a href="https://github.com/modelscript/modelscript/tree/main/packages/runtime/src/simulation/b2b_verifier.ts" target="_blank" rel="noreferrer"><code>packages/runtime/src/simulation/b2b_verifier.ts</code></a> and <code>UnifiedVerifier</code> in <a href="https://github.com/modelscript/modelscript/tree/main/packages/runtime/src/simulation/unified_verifier.ts" target="_blank" rel="noreferrer"><code>packages/runtime/src/simulation/unified_verifier.ts</code></a></li></ul><hr><h2 id="_1-spacer-chc-engine-generalized-pdr" tabindex="-1">1. Spacer CHC Engine (Generalized PDR) <a class="header-anchor" href="#_1-spacer-chc-engine-generalized-pdr" aria-label="Permalink to &quot;1. Spacer CHC Engine (Generalized PDR)&quot;">​</a></h2><h3 id="academic-citations" tabindex="-1">Academic Citations <a class="header-anchor" href="#academic-citations" aria-label="Permalink to &quot;Academic Citations&quot;">​</a></h3><ul><li><strong>Komuravelli, A., Gurfinkel, A., &amp; Chaki, S. (2014)</strong>. <em>&quot;SMT-Based Model Checking for Recursive Programs.&quot;</em><br><strong>Computer Aided Verification (CAV 2014)</strong>, LNCS 8559, pp. 17–34.<br> DOI: <a href="https://doi.org/10.1007/978-3-319-08867-9_2" target="_blank" rel="noreferrer">10.1007/978-3-319-08867-9_2</a></li><li><strong>Hoder, K., &amp; Bjørner, N. (2012)</strong>. <em>&quot;Generalized Property Directed Reachability.&quot;</em><br><strong>Theory and Applications of Satisfiability Testing (SAT 2012)</strong>, LNCS 7317, pp. 157–171.<br> DOI: <a href="https://doi.org/10.1007/978-3-642-31612-8_13" target="_blank" rel="noreferrer">10.1007/978-3-642-31612-8_13</a></li></ul><h3 id="modelscript-rationale-modifications" tabindex="-1">ModelScript Rationale &amp; Modifications <a class="header-anchor" href="#modelscript-rationale-modifications" aria-label="Permalink to &quot;ModelScript Rationale &amp; Modifications&quot;">​</a></h3><p>Constrained Horn Clauses (CHCs) represent systems of logical relations of the form: $$\\forall X. ; \\phi(X) \\land P_1(X) \\land \\dots \\land P_k(X) \\implies H(X)$$ Spacer solves CHCs by combining inductive generalization, Craig interpolation, and under-approximated reachability trees without bounding the unrolling depth. In ModelScript, Spacer verifies infinite-state state machine transitions and recursive cyber-physical control architectures.</p><ul><li><strong>Modifications</strong>: Directly integrates with ModelScript&#39;s in-WASM CDCL SAT core and Craig interpolator; implements specialized heuristics for linear real arithmetic over cyber-physical invariants.</li></ul><hr><h2 id="_2-ic3-property-directed-reachability-pdr" tabindex="-1">2. IC3 / Property Directed Reachability (PDR) <a class="header-anchor" href="#_2-ic3-property-directed-reachability-pdr" aria-label="Permalink to &quot;2. IC3 / Property Directed Reachability (PDR)&quot;">​</a></h2><h3 id="academic-citations-1" tabindex="-1">Academic Citations <a class="header-anchor" href="#academic-citations-1" aria-label="Permalink to &quot;Academic Citations&quot;">​</a></h3><ul><li><strong>Bradley, A. R. (2011)</strong>. <em>&quot;SAT-based model checking without unrolling.&quot;</em><br><strong>VMCAI 2011</strong>, LNCS 6538, pp. 70–87.<br> DOI: <a href="https://doi.org/10.1007/978-3-642-18275-4_7" target="_blank" rel="noreferrer">10.1007/978-3-642-18275-4_7</a></li><li><strong>Een, N., Mishchenko, A., &amp; Brayton, R. (2011)</strong>. <em>&quot;Efficient implementation of property directed reachability.&quot;</em><br><strong>Formal Methods in Computer-Aided Design (FMCAD 2011)</strong>, pp. 125–134.</li></ul><h3 id="modelscript-rationale-modifications-1" tabindex="-1">ModelScript Rationale &amp; Modifications <a class="header-anchor" href="#modelscript-rationale-modifications-1" aria-label="Permalink to &quot;ModelScript Rationale &amp; Modifications&quot;">​</a></h3><p>Proves whether safety property $P$ holds across all reachable states of a discrete or hybrid transition system without unrolling the transition relation $T(s, s&#39;)$ to a fixed horizon $k$.</p><ul><li><strong>Modifications</strong>: Maintains inductive clause frames $F_0, F_1, \\dots, F_k$ where $F_i$ over-approximates states reachable in up to $i$ steps; uses counterexample-guided abstraction refinement (CEGAR) to block Proof Obligations (POBs); propagates clauses forward to find an inductive invariant ($F_i \\equiv F_{i+1}$) proving unbounded safety.</li></ul><hr><h2 id="_3-stochastic-barrier-certificates-wasm-stochastic-barrier-ts" tabindex="-1">3. Stochastic Barrier Certificates (<code>wasm_stochastic_barrier.ts</code>) <a class="header-anchor" href="#_3-stochastic-barrier-certificates-wasm-stochastic-barrier-ts" aria-label="Permalink to &quot;3. Stochastic Barrier Certificates (`wasm_stochastic_barrier.ts`)&quot;">​</a></h2><h3 id="academic-citations-2" tabindex="-1">Academic Citations <a class="header-anchor" href="#academic-citations-2" aria-label="Permalink to &quot;Academic Citations&quot;">​</a></h3><ul><li><strong>Prajna, S., Jadbabaie, A., &amp; Pappas, G. J. (2007)</strong>. <em>&quot;A framework for worst-case and stochastic safety verification using barrier certificates.&quot;</em><br><strong>IEEE Transactions on Automatic Control</strong>, 52(8), pp. 1415–1428.<br> DOI: <a href="https://doi.org/10.1109/TAC.2007.902736" target="_blank" rel="noreferrer">10.1109/TAC.2007.902736</a></li><li><strong>Kushner, H. J. (1967)</strong>. <em>Stochastic Stability and Control.</em><br><strong>Academic Press</strong>.</li></ul><h3 id="modelscript-rationale-modifications-2" tabindex="-1">ModelScript Rationale &amp; Modifications <a class="header-anchor" href="#modelscript-rationale-modifications-2" aria-label="Permalink to &quot;ModelScript Rationale &amp; Modifications&quot;">​</a></h3><p>For continuous-time stochastic differential equations (Itô diffusions) driven by standard Wiener processes $W_t$: $$dx(t) = f(x) , dt + \\sigma(x) , dW_t$$ deterministic trajectories do not exist, and safety verification requires bounding the tail probability that $x(t)$ ever enters an unsafe region $\\mathcal{X}_u = { x \\mid |x|_2 \\ge r_u }$.</p><p><code>StochasticBarrierSynthesizer</code> (<code>packages/runtime/src/analysis/wasm_stochastic_barrier.ts</code>) synthesizes non-negative supermartingale barrier candidates $B(x) = x^T P x \\ge 0$ using the <strong>infinitesimal generator</strong> $\\mathcal{L}$ of the Itô process: $$\\mathcal{L} B(x) = \\nabla B(x) \\cdot f(x) + \\frac{1}{2} \\text{tr}!\\left(\\sigma(x) \\sigma(x)^T \\nabla^2 B(x)\\right) \\le -c$$</p><ul><li><strong>Doob&#39;s Maximal Supermartingale Inequality</strong>: Bounds the infinite-horizon and finite-horizon probability of unsafe set entry via: $$\\mathbb{P}!\\left(\\sup_{t \\ge 0} |x(t)|<em>2 \\ge r_u\\right) \\le \\frac{B(x_0) + \\frac{\\text{tr}(\\Sigma P)}{2 \\alpha}}{\\lambda</em>{\\min}(P) r_u^2} \\le \\delta_{\\text{risk}}$$ where $\\Sigma = \\sigma(0)\\sigma(0)^T$ is the diffusion noise covariance and $\\alpha$ is the linearized drift decay rate.</li><li><strong>Soundness &amp; Rigor Reporting</strong>: Emits structured <code>VerificationVerdict</code> diagnostics distinguishing fast linearized quadratic risk estimates from Sum-of-Squares (SOS) / LP certified supermartingales.</li></ul><hr><h2 id="_4-webgpu-datalog-owl-2-rl-saturation-reasoner-webgpu-reasoner-ts" tabindex="-1">4. WebGPU Datalog / OWL 2 RL Saturation Reasoner (<code>webgpu_reasoner.ts</code>) <a class="header-anchor" href="#_4-webgpu-datalog-owl-2-rl-saturation-reasoner-webgpu-reasoner-ts" aria-label="Permalink to &quot;4. WebGPU Datalog / OWL 2 RL Saturation Reasoner (`webgpu_reasoner.ts`)&quot;">​</a></h2><h3 id="academic-citations-3" tabindex="-1">Academic Citations <a class="header-anchor" href="#academic-citations-3" aria-label="Permalink to &quot;Academic Citations&quot;">​</a></h3><ul><li><strong>Motik, B., Patel-Schneider, P. F., &amp; Parsia, B. (2012)</strong>. <em>&quot;OWL 2 Web Ontology Language: Profiles (Second Edition) — OWL 2 RL.&quot;</em><br><strong>W3C Recommendation</strong>. <a href="https://www.w3.org/TR/owl2-profiles/" target="_blank" rel="noreferrer">https://www.w3.org/TR/owl2-profiles/</a></li><li><strong>Warshall, S. (1962)</strong>. <em>&quot;A theorem on Boolean matrices.&quot;</em><br><strong>Journal of the ACM</strong>, 9(1), pp. 11–12. DOI: <a href="https://doi.org/10.1145/321105.321107" target="_blank" rel="noreferrer">10.1145/321105.321107</a></li></ul><h3 id="modelscript-rationale-modifications-3" tabindex="-1">ModelScript Rationale &amp; Modifications <a class="header-anchor" href="#modelscript-rationale-modifications-3" aria-label="Permalink to &quot;ModelScript Rationale &amp; Modifications&quot;">​</a></h3><p>Large-scale systems engineering ontologies (<code>languages/owl2/</code> and SysML v2 KerML specialization hierarchies) contain $10^5$ to $10^7$ ABox/TBox assertions. Evaluating transitive role closures (<code>subClassOf</code>, <code>partOf</code>, <code>satisfies</code>) and SHACL numeric property constraints sequentially on the CPU becomes a bottleneck during workspace-wide verification.</p><p><code>WebGPUOntologyReasoner</code> (<code>packages/runtime/src/gpu/webgpu_reasoner.ts</code>) implements a massively parallel GPU relational join and saturation co-processor with seamless CPU SIMD bitset fallback:</p><ul><li><strong>Bit-Packed Adjacency Matrix (<code>BitsetGraph</code>)</strong>: Encodes an $N \\times N$ directed graph as a flat <code>Uint32Array</code> where each node row $u$ occupies $\\lceil N / 32 \\rceil$ 32-bit words, achieving $32\\times$ memory compression and single-instruction bitwise row unions.</li><li><strong>Parallel Logarithmic Doubling in WGSL (<code>TRANSITIVE_CLOSURE_WGSL</code>)</strong>: Dispatches compute workgroups (<code>workgroups = ceil(N / 64)</code>) over ping-pong storage buffers (<code>bufIn</code>, <code>bufOut</code>) for $\\lceil \\log_2 N \\rceil + 1$ doubling rounds, computing the full reflexive-transitive closure $R^*$ in $\\mathcal{O}(\\log N)$ GPU passes.</li><li><strong>Parallel SHACL Constraint Kernel (<code>SHACL_VALIDATION_WGSL</code>)</strong>: Validates <code>SHACLNumericConstraint</code> bounds (<code>minInclusive</code>, <code>maxInclusive</code>, <code>expectedClassId</code>) across strided <code>Float32Array</code> instance attribute tables and writes compact violation bitsets.</li></ul><hr><h2 id="_5-iso-26262-do-178c-back-to-back-equivalence-verification-b2b-verifier-ts-v-cycle-verifier-ts" tabindex="-1">5. ISO 26262 / DO-178C Back-to-Back Equivalence Verification (<code>b2b_verifier.ts</code>, <code>v_cycle_verifier.ts</code>) <a class="header-anchor" href="#_5-iso-26262-do-178c-back-to-back-equivalence-verification-b2b-verifier-ts-v-cycle-verifier-ts" aria-label="Permalink to &quot;5. ISO 26262 / DO-178C Back-to-Back Equivalence Verification (`b2b_verifier.ts`, `v_cycle_verifier.ts`)&quot;">​</a></h2><h3 id="academic-citations-4" tabindex="-1">Academic Citations <a class="header-anchor" href="#academic-citations-4" aria-label="Permalink to &quot;Academic Citations&quot;">​</a></h3><ul><li><strong>ISO 26262-6:2018 &amp; ISO 26262-8:2018</strong>. <em>Road vehicles — Functional safety — Part 6: Product development at the software level (Table 7: Back-to-back comparison test between model and code) &amp; Part 8: Supporting processes (Clause 11: Confidence in the use of software tools, TCL1).</em></li><li><strong>RTCA DO-178C /DO-331 (2011)</strong>. <em>Software Considerations in Airborne Systems and Equipment Certification — Model-Based Development and Verification Supplement.</em></li></ul><h3 id="modelscript-rationale-modifications-4" tabindex="-1">ModelScript Rationale &amp; Modifications <a class="header-anchor" href="#modelscript-rationale-modifications-4" aria-label="Permalink to &quot;ModelScript Rationale &amp; Modifications&quot;">​</a></h3><p>Safety-critical automotive (ISO 26262 ASIL-D) and avionics (DO-178C DAL-A) standards require proving that generated embedded production code (zero-allocation C99 or standalone WASM FMU artifacts) is numerically and behaviorally equivalent to the high-level specification model (SysML v2 / Modelica).</p><p><code>B2BEquivalenceVerifier</code> (<code>packages/runtime/src/simulation/b2b_verifier.ts</code>, orchestrated by <code>UnifiedVerifier</code> in <code>packages/runtime/src/simulation/unified_verifier.ts</code>) automates end-to-end <strong>Model-in-the-Loop (MiL) vs. Software-in-the-Loop (SiL)</strong> back-to-back verification:</p><ol><li><strong>MiL Reference Trajectory Execution</strong>: Simulates the high-level DAE arena (<code>simulateArenaAsync</code>) over $[t_{\\text{start}}, t_{\\text{stop}}]$ to obtain reference trajectories $y^{\\text{MiL}}_j(t)$.</li><li><strong>Standalone C99 Code Generation &amp; Cryptographic Hashing</strong>: Invokes <code>generateStandaloneCSources</code> (<code>@modelscript/exchange/fmu</code>) to emit self-contained, zero-allocation C99 sources (<code>&lt;Model&gt;_standalone.h</code>, <code>&lt;Model&gt;_standalone.c</code>), computing a SHA-256 artifact digest (<code>cSourceHash</code>) for V-cycle traceability.</li><li><strong>Automated Test Harness &amp; Native Compilation</strong>: Synthesizes a deterministic C99 fixed-step RK4 test harness (<code>&lt;Model&gt;_b2b_harness.c</code>), compiles the binary via <code>gcc -O2 -Wall -Wextra -std=c99 -lm</code>, and streams CSV output trajectories $y^{\\text{SiL}}_j(t_k)$.</li><li><strong>Bisimulation &amp; Signal-Tolerance Equivalence Checking</strong>: Aligns SiL samples against binary-searched linearly interpolated MiL trajectories and verifies the combined absolute/relative tolerance envelope across all $K$ time steps and $M$ output signals: $$\\forall j \\in {1, \\dots, M}, ; \\forall k \\in {1, \\dots, K}: \\quad \\left| y^{\\text{MiL}}<em>j(t_k) - y^{\\text{SiL}}<em>j(t_k) \\right| \\le \\epsilon</em>{\\text{abs}} + \\epsilon</em>{\\text{rel}} \\left| y^{\\text{MiL}}_j(t_k) \\right|$$</li></ol><hr><h2 id="upstream-downstream-pipeline-connections" tabindex="-1">Upstream &amp; Downstream Pipeline Connections <a class="header-anchor" href="#upstream-downstream-pipeline-connections" aria-label="Permalink to &quot;Upstream &amp; Downstream Pipeline Connections&quot;">​</a></h2><ul><li><strong>Upstream Inputs</strong>: <ul><li>State machine models and safety requirements from <a href="./../languages/sysml2.html"><code>SysML v2</code></a>.</li><li>Mode switching, discrete <code>when</code> / <code>if</code> clauses, and continuous/stochastic DAE arenas lowered from <a href="./../languages/modelica.html"><code>Modelica</code></a>.</li><li>OWL 2 TBox/ABox ontological triples from <a href="./../languages/owl2.html"><code>OWL2</code></a>.</li></ul></li><li><strong>Downstream Consumers</strong>: <ul><li>Verifies architectural safety contracts, stochastic risk bounds, and ISO 26262 MiL/SiL equivalence in <code>msx verify</code>.</li><li>Feeds theory lemmas and transitive subsumption closures into <a href="./theory-coordinator.html"><code>Nelson-Oppen Coordinator</code></a>.</li></ul></li></ul>',44)])])}const h=i(o,[["render",s]]);export{u as __pageData,h as default};
